module find_playlist (\n    input clk,\n    input rst_n,\n    input start,\n    input [6:0] n,\n    input [7:0] artist_idx [0:99],\n    input [5:0] neighbor_count [0:99],\n    input [6:0] neighbors [0:99][0:39],\n    output reg [6:0] path [0:8],\n    output reg found,\n    output reg done\n);\n\n    localparam IDLE = 4'd0;\n    localparam INIT = 4'd1;\n    localparam START_SEARCH = 4'd2;\n    localparam CHECK_NEIGHBOR = 4'd3;\n    localparam CHECK_VALIDITY = 4'd4;\n    localparam UPDATE_PATH = 4'd5;\n    localparam BACKTRACK = 4'd6;\n    localparam FOUND = 4'd7;\n    localparam FAIL = 4'd8;\n\n    reg [3:0] state;\n    reg [3:0] current_depth;\n    reg [6:0] song_stack [0:8];\n    reg [5:0] neighbor_idx_stack [0:8];\n    reg [99:0] artist_mask;\n    reg [6:0] start_song_idx;\n    reg [6:0] candidate_song;\n    reg [5:0] temp_idx;\n    reg duplicate;\n    reg artist_used;\n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            found <= 1'b0;\n            done <= 1'b0;\n            current_depth <= 4'd0;\n            artist_mask <= 100'd0;\n            start_song_idx <= 7'd0;\n            for (i = 0; i < 9; i = i + 1) begin\n                song_stack[i] <= 7'd0;\n                neighbor_idx_stack[i] <= 6'd0;\n                path[i] <= 7'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    found <= 1'b0;\n                    done <= 1'b0;\n                    if (start) state <= INIT;\n                end\n                INIT: begin\n                    current_depth <= 4'd0;\n                    artist_mask <= 100'd0;\n                    start_song_idx <= 7'd0;\n                    for (i = 0; i < 9; i = i + 1) begin\n                        neighbor_idx_stack[i] <= 6'd0;\n                    end\n                    state <= START_SEARCH;\n                end\n                START_SEARCH: begin\n                    if (current_depth == 4'd0) begin\n                        if (start_song_idx < n) begin\n                            song_stack[0] <= start_song_idx;\n                            artist_mask[artist_idx[start_song_idx]] <= 1'b1;\n                            current_depth <= 4'd1;\n                            neighbor_idx_stack[0] <= 6'd0;\n                            state <= CHECK_NEIGHBOR;\n                        end else begin\n                            state <= FAIL;\n                        end\n                    end else begin\n                        state <= CHECK_NEIGHBOR;\n                    end\n                end\n                CHECK_NEIGHBOR: begin\n                    if (current_depth > 4'd0 && current_depth < 4'd9) begin\n                        temp_idx = current_depth - 4'd1;\n                        if (neighbor_idx_stack[temp_idx] < neighbor_count[song_stack[temp_idx]]) begin\n                            candidate_song <= neighbors[song_stack[temp_idx]][neighbor_idx_stack[temp_idx]];\n                            neighbor_idx_stack[temp_idx] <= neighbor_idx_stack[temp_idx] + 6'd1;\n                            state <= CHECK_VALIDITY;\n                        end else begin\n                            state <= BACKTRACK;\n                        end\n                    end else if (current_depth == 4'd9) begin\n                        state <= FOUND;\n                    end else begin\n                        state <= BACKTRACK;\n                    end\n                end\n                CHECK_VALIDITY: begin\n                    duplicate = 1'b0;\n                    for (i = 0; i < current_depth; i = i + 1) begin\n                        if (song_stack[i] == candidate_song) duplicate = 1'b1;\n                    end\n                    artist_used = artist_mask[artist_idx[candidate_song]];\n                    if (!duplicate && !artist_used) begin\n                        state <= UPDATE_PATH;\n                    end else begin\n                        state <= CHECK_NEIGHBOR;\n                    end\n                end\n                UPDATE_PATH: begin\n                    song_stack[current_depth] <= candidate_song;\n                    artist_mask[artist_idx[candidate_song]] <= 1'b1;\n                    neighbor_idx_stack[current_depth] <= 6'd0;\n                    current_depth <= current_depth + 4'd1;\n                    if (current_depth + 4'd1 == 4'd9) begin\n                        state <= FOUND;\n                    end else begin\n                        state <= CHECK_NEIGHBOR;\n                    end\n                end\n                BACKTRACK: begin\n                    if (current_depth == 4'd0) begin\n                        start_song_idx <= start_song_idx + 7'd1;\n                        state <= START_SEARCH;\n                    end else begin\n                        artist_mask[artist_idx[song_stack[current_depth-4'd1]]] <= 1'b0;\n                        current_depth <= current_depth - 4'd1;\n                        state <= CHECK_NEIGHBOR;\n                    end\n                end\n                FOUND: begin\n                    for (i = 0; i < 9; i = i + 1) begin\n                        path[i] <= song_stack[i];\n                    end\n                    found <= 1'b1;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                FAIL: begin\n                    found <= 1'b0;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule